import React from 'react';
import { Outlet, NavLink } from 'react-router-dom';

// SỬA ĐƯỜNG DẪN: Phải là ../../ để ra khỏi folder QuanLy và folder trang
import logoBgImg from '../../assets/nen_ten_web.jpg'; 
import mainBgImg from '../../assets/nen_nen.jpg';

const TrangChuQuanLy = () => {
    const menuItems = [
        { name: 'Quản lý thông báo', path: 'thong-bao' },
        { name: 'Quản lý cư dân', path: 'cu-dan' },
        { name: 'Quản lý căn hộ', path: 'can-ho' },
        { name: 'Quản lý hoá đơn', path: 'hoa-don' },
        { name: 'Quản lý yêu cầu bảo trì', path: 'bao-tri' },
        { name: 'Quản lý phương tiện', path: 'phuong-tien' },
        { name: 'Quản lý bãi đỗ xe', path: 'bai-do-xe' },
        { name: 'Báo cáo & thống kê', path: 'bao-cao' },
    ];

    return (
        <div style={{
            display: 'flex', height: '100vh', padding: '20px', gap: '20px', 
            backgroundImage: `url(${mainBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', boxSizing: 'border-box'
        }}>
            {/* Sidebar */}
            <aside style={styles.sidebar} className="glass-sidebar">
                {/* Logo Box với ảnh nền tòa nhà */}
                <div style={{...styles.logoWrapper, backgroundImage: `url(${logoBgImg})`}}>
                    <h1 style={styles.logoText}>A&RMS</h1>
                </div>

                <nav style={styles.navStack}>
                    {menuItems.map((item, index) => (
                        <NavLink 
                            key={index} 
                            to={`/dashboard-quan-ly/${item.path}`} 
                            style={({ isActive }) => ({
                                ...styles.navBtn,
                                backgroundColor: isActive ? 'rgba(139, 94, 94, 0.9)' : '#fff',
                                color: isActive ? '#fff' : '#333',
                            })}
                        >
                            {item.name}
                        </NavLink>
                    ))}
                </nav>
            </aside>

            {/* Content Area */}
            <div style={styles.rightContent}>
                <header style={styles.headerRow}>
                    <div className="glass-sidebar" style={styles.titleBox}>Hệ thống quản lý toà nhà</div>
                    <div className="glass-sidebar" style={styles.adminBox}>admin</div>
                </header>
                <main style={styles.contentMain}>
                    <Outlet />
                </main>
            </div>
        </div>
    );
};

const styles = {
    sidebar: { width: '280px', borderRadius: '30px', padding: '25px', display: 'flex', flexDirection: 'column' },
    logoWrapper: { 
        height: '110px', marginBottom: '30px', display: 'flex', alignItems: 'center', 
        justifyContent: 'center', borderRadius: '20px', backgroundSize: 'cover', 
        backgroundPosition: 'center', boxShadow: '0 4px 15px rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.2)' 
    },
    logoText: { color: '#fff', fontSize: '35px', fontWeight: '900', textShadow: '2px 2px 10px rgba(0,0,0,0.8)', margin: 0 },
    navStack: { display: 'flex', flexDirection: 'column', gap: '10px' },
    navBtn: { padding: '15px 20px', borderRadius: '25px', textDecoration: 'none', fontWeight: '600', fontSize: '14px', textAlign: 'center', transition: '0.3s' },
    rightContent: { flex: 1, display: 'flex', flexDirection: 'column', gap: '20px' },
    headerRow: { display: 'flex', gap: '20px', height: '60px' },
    titleBox: { flex: 1, borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff', fontWeight: 'bold' },
    adminBox: { width: '150px', borderRadius: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#fff' },
    contentMain: { flex: 1, display: 'flex' }
};

export default TrangChuQuanLy;
